pub(super) fn expansion__portfolio_readiness__first_source(
    mut source_refs: Value,
    mut input_data: Value,
    mut fallback: Value,
) -> Result<Value> {
    let mut refs: Value;
    refs = {
        let first = source_refs.clone();
        if truth(&first) {
            first
        } else {
            {
                let first = get(&input_data, &json!("sourceRefs"), Value::Null);
                if truth(&first) {
                    first
                } else {
                    Value::Array(vec![fallback.clone()])
                }
            }
        }
    };
    return Ok((if truth(&refs) {
        json!(values::text(&indexed(&refs, &json!(0))?))
    } else {
        fallback.clone()
    }));
}

pub(super) fn expansion__portfolio_readiness__list_of_dicts(mut value: Value) -> Result<Value> {
    return Ok((if (value.clone().is_array()) {
        {
            let mut collected_values = Vec::new();
            for current in sequence(&value)? {
                let mut item = current;
                if !(item.clone().is_object()) {
                    continue;
                }
                collected_values.push(builtin("dict", &[item.clone()])?);
            }
            Value::Array(collected_values)
        }
    } else {
        Value::Array(vec![])
    }));
}

