pub(super) fn expansion__portfolio_readiness__provider_diagnostics(
    mut config: Value,
) -> Result<Value> {
    let mut annotation_providers: Value;
    let mut artifact_providers: Value;
    let mut missing_permission_source_refs: Value;
    let mut nondeterministic_reruns: Value;
    let mut overbroad_permissions: Value;
    let mut permission_providers: Value;
    let mut provider_names: Value;
    let mut provider_set: Value;
    let mut rerun_providers: Value;
    let mut unsafe_annotations: Value;
    let mut unsafe_artifacts: Value;
    provider_names = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("providers"))?)? {
            let mut provider = current;
            if !(truth(&get(&provider, &json!("provider"), Value::Null))) {
                continue;
            }
            collected_values.push(json!(values::text(&{
                let first = get(&provider, &json!("provider"), Value::Null);
                if truth(&first) { first } else { json!("") }
            })));
        }
        Value::Array(collected_values)
    };
    provider_set = builtin("set", &[provider_names.clone()])?;
    permission_providers = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("permission_matrix"))?)? {
            let mut rule = current;
            if !(truth(&get(&rule, &json!("provider"), Value::Null))) {
                continue;
            }
            collected_values.push(json!(values::text(&{
                let first = get(&rule, &json!("provider"), Value::Null);
                if truth(&first) { first } else { json!("") }
            })));
        }
        unique(collected_values)
    };
    artifact_providers = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("artifact_policies"))?)? {
            let mut policy = current;
            if !(truth(&get(&policy, &json!("provider"), Value::Null))) {
                continue;
            }
            collected_values.push(json!(values::text(&{
                let first = get(&policy, &json!("provider"), Value::Null);
                if truth(&first) { first } else { json!("") }
            })));
        }
        unique(collected_values)
    };
    annotation_providers = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("annotation_policies"))?)? {
            let mut policy = current;
            if !(truth(&get(&policy, &json!("provider"), Value::Null))) {
                continue;
            }
            collected_values.push(json!(values::text(&{
                let first = get(&policy, &json!("provider"), Value::Null);
                if truth(&first) { first } else { json!("") }
            })));
        }
        unique(collected_values)
    };
    rerun_providers = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("rerun_policies"))?)? {
            let mut policy = current;
            if !(truth(&get(&policy, &json!("provider"), Value::Null))) {
                continue;
            }
            collected_values.push(json!(values::text(&{
                let first = get(&policy, &json!("provider"), Value::Null);
                if truth(&first) { first } else { json!("") }
            })));
        }
        unique(collected_values)
    };
    overbroad_permissions = sorted(
        &{
            let mut collected_values = Vec::new();
            for current in sequence(&indexed(&config, &json!("permission_matrix"))?)? {
                let mut rule = current;
                if !((contains(
                    &unique(vec![json!("admin"), json!("write_all"), json!("*")]),
                    &get(&rule, &json!("scope"), Value::Null),
                )) || (truth(&json!(truth(&get(
                    &rule,
                    &json!("write_repository"),
                    Value::Null
                )))))) {
                    continue;
                }
                collected_values.push(json!(values::text(&{
                    let first = get(&rule, &json!("provider"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        json!("provider")
                    }
                })));
            }
            Value::Array(collected_values)
        },
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    missing_permission_source_refs = sorted(
        &{
            let mut collected_values = Vec::new();
            for current in sequence(&indexed(&config, &json!("permission_matrix"))?)? {
                let mut rule = current;
                if !(!(truth(&get(&rule, &json!("sourceRef"), Value::Null)))) {
                    continue;
                }
                collected_values.push(json!(values::text(&{
                    let first = get(&rule, &json!("provider"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        json!("provider")
                    }
                })));
            }
            Value::Array(collected_values)
        },
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    unsafe_artifacts = sorted(
        &{
            let mut collected_values = Vec::new();
            for current in sequence(&indexed(&config, &json!("artifact_policies"))?)? {
                let mut policy = current;
                if !((!(truth(&get(&policy, &json!("redaction"), Value::Null))))
                    || (!(truth(&get(&policy, &json!("retention_days"), Value::Null))))
                    || (truth(&get(&policy, &json!("allows_raw_logs"), Value::Null))))
                {
                    continue;
                }
                collected_values.push(json!(values::text(&{
                    let first = get(&policy, &json!("provider"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        json!("provider")
                    }
                })));
            }
            Value::Array(collected_values)
        },
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    unsafe_annotations = sorted(
        &{
            let mut collected_values = Vec::new();
            for current in sequence(&indexed(&config, &json!("annotation_policies"))?)? {
                let mut policy = current;
                if !((!(truth(&get(&policy, &json!("sourceRef"), Value::Null))))
                    || (!(truth(&get(&policy, &json!("stable_target"), Value::Null))))
                    || (truth(&get(&policy, &json!("can_post_secret"), Value::Null))))
                {
                    continue;
                }
                collected_values.push(json!(values::text(&{
                    let first = get(&policy, &json!("provider"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        json!("provider")
                    }
                })));
            }
            Value::Array(collected_values)
        },
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    nondeterministic_reruns = sorted(
        &{
            let mut collected_values = Vec::new();
            for current in sequence(&indexed(&config, &json!("rerun_policies"))?)? {
                let mut policy = current;
                if !((!(truth(&get(&policy, &json!("attempt_identity"), Value::Null))))
                    || (!(truth(&get(&policy, &json!("idempotency_key"), Value::Null))))
                    || (!(truth(&get(
                        &policy,
                        &json!("preserves_previous_attempt"),
                        Value::Null,
                    )))))
                {
                    continue;
                }
                collected_values.push(json!(values::text(&{
                    let first = get(&policy, &json!("provider"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        json!("provider")
                    }
                })));
            }
            Value::Array(collected_values)
        },
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    return Ok(Value::Object(
        [
            (
                "duplicate_providers".into(),
                sorted(
                    &{
                        let mut collected_values = Vec::new();
                        for current in sequence(&provider_names)? {
                            let mut item = current;
                            if !(compare(
                                &method(&provider_names, "count", &item, &Value::Null)?,
                                &json!(1),
                            )
                            .is_gt())
                            {
                                continue;
                            }
                            collected_values.push(item.clone());
                        }
                        unique(collected_values)
                    },
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "providers_missing_permission_policy".into(),
                sorted(
                    &arithmetic(&provider_set, &permission_providers, "-")?,
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "providers_missing_artifact_policy".into(),
                sorted(
                    &arithmetic(&provider_set, &artifact_providers, "-")?,
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "providers_missing_annotation_policy".into(),
                sorted(
                    &arithmetic(&provider_set, &annotation_providers, "-")?,
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "providers_missing_rerun_policy".into(),
                sorted(
                    &arithmetic(&provider_set, &rerun_providers, "-")?,
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "overbroad_permission_providers".into(),
                sorted(
                    &builtin("set", &[overbroad_permissions.clone()])?,
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "permission_source_ref_missing_providers".into(),
                missing_permission_source_refs.clone(),
            ),
            (
                "unsafe_artifact_policy_providers".into(),
                unsafe_artifacts.clone(),
            ),
            (
                "unsafe_annotation_policy_providers".into(),
                unsafe_annotations.clone(),
            ),
            (
                "nondeterministic_rerun_providers".into(),
                nondeterministic_reruns.clone(),
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

pub(super) fn expansion__portfolio_readiness__provider_findings(
    mut config: Value,
    mut diagnostics: Value,
    mut source_ref: Value,
) -> Result<Value> {
    let mut findings: Value;
    let mut missing: Value;
    let mut missing_fields: Value;
    findings = Value::Array(vec![]);
    missing = indexed(
        &expansion__portfolio_readiness__provider_summary(config.clone())?,
        &json!("missing_required_providers"),
    )?;
    if truth(&missing) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_required_provider_missing"),
                json!(format!(
                    "Provider matrix missing: {}.",
                    values::text(&json!(strings(&missing)?.join(&values::text(&json!(", ")))))
                )),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    for current in sequence(&indexed(&config, &json!("providers"))?)? {
        let mut provider = current;
        missing_fields = {
            let mut collected_values = Vec::new();
            for current in sequence(&Value::Array(vec![
                json!("commit_identity"),
                json!("review_identity"),
                json!("run_attempt"),
                json!("artifact_lifetime"),
                json!("annotation_target"),
                json!("rerun_semantics"),
            ]))? {
                let mut key = current;
                if !(!(truth(&get(&provider, &key, Value::Null)))) {
                    continue;
                }
                collected_values.push(key.clone());
            }
            Value::Array(collected_values)
        };
        if truth(&missing_fields) {
            {
                let incoming = expansion__portfolio_readiness__finding(
                    json!("provider_integration_identity_semantics_incomplete"),
                    json!(format!(
                        "{} missing: {}.",
                        values::text(&get(&provider, &json!("provider"), json!("provider"))),
                        values::text(&json!(
                            strings(&missing_fields)?.join(&values::text(&json!(", ")))
                        ))
                    )),
                    source_ref.clone(),
                    json!("high"),
                )?;
                edit(&mut findings, "append", incoming)?;
            }
        }
    }
    if truth(&indexed(&diagnostics, &json!("duplicate_providers"))?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_duplicate_provider"),
                json!("Provider matrix contains duplicate provider entries."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("providers_missing_permission_policy"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_permission_policy_missing"),
                json!("Provider permission policy missing for one or more providers."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("providers_missing_artifact_policy"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_artifact_policy_missing"),
                json!("Provider artifact retention/redaction policy missing."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("providers_missing_annotation_policy"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_annotation_policy_missing"),
                json!("Provider annotation target policy missing."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("providers_missing_rerun_policy"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_rerun_policy_missing"),
                json!("Provider rerun policy missing."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("permission_source_ref_missing_providers"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_permission_source_ref_missing"),
                json!("Provider permission rules require sourceRef."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("unsafe_artifact_policy_providers"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_artifact_policy_unsafe"),
                json!(
                    "Provider artifact policy must set retention and redaction and deny raw logs."
                ),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("unsafe_annotation_policy_providers"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_annotation_policy_unsafe"),
                json!("Provider annotation policy must use stable targets and safe payloads."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("nondeterministic_rerun_providers"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_rerun_nondeterministic"),
                json!("Provider rerun policy must preserve attempt identity and idempotency."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if !(truth(&indexed(&config, &json!("minimum_permissions_declared"))?)) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_minimum_permissions_missing"),
                json!("Provider integrations must declare minimum permissions."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(&config, &json!("ambiguous_identity_detected"))?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_ambiguous_identity_hard_dq"),
                json!("Ambiguous provider identity must not become silent advisory output."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if (truth(&indexed(&config, &json!("overbroad_permission_detected"))?))
        || (truth(&indexed(
            &diagnostics,
            &json!("overbroad_permission_providers"),
        )?))
    {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_overbroad_permission_denied"),
                json!("Broad or admin provider permission is denied."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(&config, &json!("raw_token_present"))?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("provider_integration_raw_token_denied"),
                json!("Provider report must not expose raw provider tokens."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    return Ok(findings.clone());
}

pub(super) fn expansion__portfolio_readiness__provider_summary(mut config: Value) -> Result<Value> {
    let mut covered: Value;
    let mut missing: Value;
    covered = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("providers"))?)? {
            let mut provider = current;
            if !(contains(
                &unique(vec![json!("supported"), json!("partial")]),
                &get(&provider, &json!("support_state"), Value::Null),
            )) {
                continue;
            }
            collected_values.push(get(&provider, &json!("provider"), Value::Null));
        }
        unique(collected_values)
    };
    missing = sorted(
        &arithmetic(
            &builtin("set", &[indexed(&config, &json!("required_providers"))?])?,
            &covered,
            "-",
        )?,
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    return Ok(Value::Object(
        [
            (
                "provider_count".into(),
                builtin("len", &[indexed(&config, &json!("providers"))?])?,
            ),
            (
                "required_provider_count".into(),
                builtin("len", &[indexed(&config, &json!("required_providers"))?])?,
            ),
            ("missing_required_providers".into(), missing.clone()),
            (
                "minimum_permissions_declared".into(),
                indexed(&config, &json!("minimum_permissions_declared"))?,
            ),
            (
                "permission_rule_count".into(),
                builtin("len", &[indexed(&config, &json!("permission_matrix"))?])?,
            ),
            (
                "artifact_policy_count".into(),
                builtin("len", &[indexed(&config, &json!("artifact_policies"))?])?,
            ),
            (
                "annotation_policy_count".into(),
                builtin("len", &[indexed(&config, &json!("annotation_policies"))?])?,
            ),
            (
                "rerun_policy_count".into(),
                builtin("len", &[indexed(&config, &json!("rerun_policies"))?])?,
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

