pub(super) fn expansion__portfolio_readiness__runner_diagnostics(
    mut config: Value,
) -> Result<Value> {
    let mut capabilities: Value;
    let mut dialect_id: Value;
    let mut dialect_ids: Value;
    let mut expected_summary: Value;
    let mut malformed_missing_negative: Value;
    let mut missing: Value;
    let mut missing_capabilities: Value;
    let mut missing_source_refs: Value;
    let mut noisy_without_filter: Value;
    let mut observed_summary: Value;
    let mut partial_parse_without_gap: Value;
    let mut required_capabilities: Value;
    let mut summary_mismatches: Value;
    let mut unsupported: Value;
    let mut unsupported_capabilities: Value;
    dialect_ids = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("dialects"))?)? {
            let mut dialect = current;
            if !((truth(&get(&dialect, &json!("dialect"), Value::Null)))
                || (truth(&get(&dialect, &json!("id"), Value::Null))))
            {
                continue;
            }
            collected_values.push(json!(values::text(&{
                let first = get(&dialect, &json!("dialect"), Value::Null);
                if truth(&first) {
                    first
                } else {
                    {
                        let first = get(&dialect, &json!("id"), Value::Null);
                        if truth(&first) { first } else { json!("") }
                    }
                }
            })));
        }
        Value::Array(collected_values)
    };
    required_capabilities = builtin("set", &[indexed(&config, &json!("required_capabilities"))?])?;
    missing_capabilities = json!({});
    unsupported_capabilities = json!({});
    summary_mismatches = Value::Array(vec![]);
    missing_source_refs = Value::Array(vec![]);
    noisy_without_filter = Value::Array(vec![]);
    partial_parse_without_gap = Value::Array(vec![]);
    malformed_missing_negative = Value::Array(vec![]);
    for current in sequence(&indexed(&config, &json!("dialects"))?)? {
        let mut dialect = current;
        dialect_id = json!(values::text(&{
            let first = get(&dialect, &json!("dialect"), Value::Null);
            if truth(&first) {
                first
            } else {
                {
                    let first = get(&dialect, &json!("id"), Value::Null);
                    if truth(&first) {
                        first
                    } else {
                        json!("dialect")
                    }
                }
            }
        }));
        capabilities = builtin(
            "set",
            &[expansion__portfolio_readiness__strings(get(
                &dialect,
                &json!("capabilities"),
                Value::Array(vec![]),
            ))?],
        )?;
        unsupported = builtin(
            "set",
            &[expansion__portfolio_readiness__strings(get(
                &dialect,
                &json!("unsupported_capabilities"),
                Value::Array(vec![]),
            ))?],
        )?;
        missing = sorted(
            &arithmetic(&required_capabilities, &capabilities, "-")?,
            |v: &Value| Ok(v.clone()),
            false,
        )?;
        if truth(&missing) {
            {
                let incoming = missing.clone();
                let index = dialect_id.clone();
                set_index(&mut missing_capabilities, &index, incoming)?;
            }
        }
        if truth(&unsupported) {
            {
                let incoming = sorted(&unsupported, |v: &Value| Ok(v.clone()), false)?;
                let index = dialect_id.clone();
                set_index(&mut unsupported_capabilities, &index, incoming)?;
            }
        }
        if !(truth(&get(&dialect, &json!("sourceRef"), Value::Null))) {
            {
                let incoming = dialect_id.clone();
                edit(&mut missing_source_refs, "append", incoming)?;
            }
        }
        expected_summary = builtin(
            "dict",
            &[{
                let first = get(&dialect, &json!("expected_summary"), json!({}));
                if truth(&first) { first } else { json!({}) }
            }],
        )?;
        observed_summary = builtin(
            "dict",
            &[{
                let first = get(&dialect, &json!("observed_summary"), json!({}));
                if truth(&first) { first } else { json!({}) }
            }],
        )?;
        if (truth(&expected_summary))
            && (truth(&observed_summary))
            && (!equal(&expected_summary, &observed_summary))
        {
            {
                let incoming = dialect_id.clone();
                edit(&mut summary_mismatches, "append", incoming)?;
            }
        }
        if (truth(&get(&dialect, &json!("noise_lines"), Value::Null)))
            && (!(truth(&get(&dialect, &json!("noise_filter_ref"), Value::Null))))
        {
            {
                let incoming = dialect_id.clone();
                edit(&mut noisy_without_filter, "append", incoming)?;
            }
        }
        if (equal(
            &get(&dialect, &json!("parser_status"), Value::Null),
            &json!("partial"),
        )) && (!(truth(&get(&dialect, &json!("capability_gap_ref"), Value::Null))))
        {
            {
                let incoming = dialect_id.clone();
                edit(&mut partial_parse_without_gap, "append", incoming)?;
            }
        }
        if !(truth(&get(&dialect, &json!("malformed_fixture_ref"), Value::Null))) {
            {
                let incoming = dialect_id.clone();
                edit(&mut malformed_missing_negative, "append", incoming)?;
            }
        }
    }
    return Ok(Value::Object(
        [
            (
                "duplicate_dialects".into(),
                sorted(
                    &{
                        let mut collected_values = Vec::new();
                        for current in sequence(&dialect_ids)? {
                            let mut item = current;
                            if !(compare(
                                &method(&dialect_ids, "count", &item, &Value::Null)?,
                                &json!(1),
                            )
                            .is_gt())
                            {
                                continue;
                            }
                            collected_values.push(item.clone());
                        }
                        unique(collected_values)
                    },
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
            (
                "missing_capabilities_by_dialect".into(),
                missing_capabilities.clone(),
            ),
            (
                "unsupported_capabilities_by_dialect".into(),
                unsupported_capabilities.clone(),
            ),
            (
                "summary_mismatch_dialects".into(),
                sorted(&summary_mismatches, |v: &Value| Ok(v.clone()), false)?,
            ),
            (
                "missing_source_ref_dialects".into(),
                sorted(&missing_source_refs, |v: &Value| Ok(v.clone()), false)?,
            ),
            (
                "noisy_without_filter_dialects".into(),
                sorted(&noisy_without_filter, |v: &Value| Ok(v.clone()), false)?,
            ),
            (
                "partial_parse_without_gap_dialects".into(),
                sorted(&partial_parse_without_gap, |v: &Value| Ok(v.clone()), false)?,
            ),
            (
                "malformed_fixture_missing_dialects".into(),
                sorted(
                    &malformed_missing_negative,
                    |v: &Value| Ok(v.clone()),
                    false,
                )?,
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

pub(super) fn expansion__portfolio_readiness__runner_findings(
    mut config: Value,
    mut diagnostics: Value,
    mut source_ref: Value,
) -> Result<Value> {
    let mut findings: Value;
    let mut missing: Value;
    findings = Value::Array(vec![]);
    missing = indexed(
        &expansion__portfolio_readiness__runner_summary(config.clone())?,
        &json!("missing_required_families"),
    )?;
    if truth(&missing) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_required_family_missing"),
                json!(format!(
                    "Runner family coverage missing: {}.",
                    values::text(&json!(strings(&missing)?.join(&values::text(&json!(", ")))))
                )),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    for current in sequence(&indexed(&config, &json!("dialects"))?)? {
        let mut dialect = current;
        if !(truth(&get(
            &dialect,
            &json!("conformance_fixture_ref"),
            Value::Null,
        ))) {
            {
                let incoming = expansion__portfolio_readiness__finding(
                    json!("runner_dialect_conformance_fixture_missing"),
                    json!(format!(
                        "{} missing conformance fixture.",
                        values::text(&get(&dialect, &json!("dialect"), json!("dialect")))
                    )),
                    source_ref.clone(),
                    json!("high"),
                )?;
                edit(&mut findings, "append", incoming)?;
            }
        }
    }
    if truth(&indexed(
        &config,
        &json!("unsupported_capability_gap_detected"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_unsupported_capability_gap"),
                json!("Unsupported runner output must emit a capability gap."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &config,
        &json!("claim_without_conformance_detected"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_claim_without_conformance"),
                json!("Runner support claim without conformance fixture blocks product-ready."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(&diagnostics, &json!("duplicate_dialects"))?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_duplicate_dialect"),
                json!("Runner dialect matrix contains duplicate dialect ids."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("missing_capabilities_by_dialect"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_required_capability_missing"),
                json!("Runner dialect is missing required parser capabilities."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(&diagnostics, &json!("summary_mismatch_dialects"))?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_summary_mismatch"),
                json!("Runner dialect observed summary differs from expected fixture summary."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("missing_source_ref_dialects"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_source_ref_missing"),
                json!("Runner dialect claims require sourceRef."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("noisy_without_filter_dialects"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_noise_filter_missing"),
                json!("Noisy runner output requires ignored-noise filter reference."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("partial_parse_without_gap_dialects"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_partial_parse_gap_missing"),
                json!("Partial parser support requires explicit capability gap ref."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(
        &diagnostics,
        &json!("malformed_fixture_missing_dialects"),
    )?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_malformed_fixture_missing"),
                json!("Runner dialect requires malformed negative fixture."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    if truth(&indexed(&config, &json!("raw_log_retention_denied"))?) {
        {
            let incoming = expansion__portfolio_readiness__finding(
                json!("runner_dialect_raw_log_retention_denied"),
                json!("Runner dialect report must not retain raw logs as evidence."),
                source_ref.clone(),
                json!("high"),
            )?;
            edit(&mut findings, "append", incoming)?;
        }
    }
    return Ok(findings.clone());
}

pub(super) fn expansion__portfolio_readiness__runner_results(mut config: Value) -> Result<Value> {
    let mut dialect_id: Value;
    let mut has_fixture: Value;
    let mut results: Value;
    results = Value::Array(vec![]);
    for current in sequence(&indexed(&config, &json!("dialects"))?)? {
        let mut dialect = current;
        dialect_id = json!(values::text(&{
            let first = get(&dialect, &json!("dialect"), Value::Null);
            if truth(&first) {
                first
            } else {
                {
                    let first = get(&dialect, &json!("id"), Value::Null);
                    if truth(&first) { first } else { json!("") }
                }
            }
        }));
        has_fixture = json!(truth(&get(
            &dialect,
            &json!("conformance_fixture_ref"),
            Value::Null
        )));
        {
            let incoming = Value::Object(
                [
                    ("case_id".into(), {
                        let first = dialect_id.clone();
                        if truth(&first) {
                            first
                        } else {
                            json!("dialect")
                        }
                    }),
                    (
                        "expected".into(),
                        Value::Object(
                            [
                                ("dialect".into(), dialect_id.clone()),
                                ("conformance_fixture_required".into(), json!(true)),
                                (
                                    "summary".into(),
                                    builtin(
                                        "dict",
                                        &[{
                                            let first = get(
                                                &dialect,
                                                &json!("expected_summary"),
                                                json!({}),
                                            );
                                            if truth(&first) { first } else { json!({}) }
                                        }],
                                    )?,
                                ),
                            ]
                            .into_iter()
                            .collect(),
                        ),
                    ),
                    (
                        "actual".into(),
                        Value::Object(
                            [
                                ("dialect".into(), dialect_id.clone()),
                                (
                                    "summary".into(),
                                    builtin(
                                        "dict",
                                        &[{
                                            let first = get(
                                                &dialect,
                                                &json!("observed_summary"),
                                                json!({}),
                                            );
                                            if truth(&first) { first } else { json!({}) }
                                        }],
                                    )?,
                                ),
                                (
                                    "ignored_noise".into(),
                                    expansion__portfolio_readiness__strings(get(
                                        &dialect,
                                        &json!("ignored_noise"),
                                        Value::Array(vec![]),
                                    ))?,
                                ),
                                (
                                    "parser_status".into(),
                                    json!(values::text(&{
                                        let first =
                                            get(&dialect, &json!("parser_status"), Value::Null);
                                        if truth(&first) {
                                            first
                                        } else {
                                            (if truth(&has_fixture) {
                                                json!("parsed")
                                            } else {
                                                json!("unparsed")
                                            })
                                        }
                                    })),
                                ),
                            ]
                            .into_iter()
                            .collect(),
                        ),
                    ),
                    ("passed".into(), {
                        let first = has_fixture.clone();
                        if !truth(&first) {
                            first
                        } else {
                            json!(equal(
                                &builtin(
                                    "dict",
                                    &[{
                                        let first =
                                            get(&dialect, &json!("expected_summary"), json!({}));
                                        if truth(&first) { first } else { json!({}) }
                                    }]
                                )?,
                                &builtin(
                                    "dict",
                                    &[{
                                        let first =
                                            get(&dialect, &json!("observed_summary"), json!({}));
                                        if truth(&first) { first } else { json!({}) }
                                    }]
                                )?
                            ))
                        }
                    }),
                ]
                .into_iter()
                .collect(),
            );
            edit(&mut results, "append", incoming)?;
        }
    }
    return Ok(results.clone());
}

pub(super) fn expansion__portfolio_readiness__runner_summary(mut config: Value) -> Result<Value> {
    let mut covered: Value;
    let mut missing: Value;
    covered = {
        let mut collected_values = Vec::new();
        for current in sequence(&indexed(&config, &json!("runner_families"))?)? {
            let mut family = current;
            if !(contains(
                &unique(vec![json!("supported"), json!("partial")]),
                &get(&family, &json!("support_state"), Value::Null),
            )) {
                continue;
            }
            collected_values.push(get(&family, &json!("family"), Value::Null));
        }
        unique(collected_values)
    };
    missing = sorted(
        &arithmetic(
            &builtin("set", &[indexed(&config, &json!("required_families"))?])?,
            &covered,
            "-",
        )?,
        |v: &Value| Ok(v.clone()),
        false,
    )?;
    return Ok(Value::Object(
        [
            (
                "runner_family_count".into(),
                builtin("len", &[indexed(&config, &json!("runner_families"))?])?,
            ),
            (
                "dialect_count".into(),
                builtin("len", &[indexed(&config, &json!("dialects"))?])?,
            ),
            ("missing_required_families".into(), missing.clone()),
            (
                "required_capability_count".into(),
                builtin("len", &[indexed(&config, &json!("required_capabilities"))?])?,
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

pub(super) fn expansion__portfolio_readiness__strings(mut value: Value) -> Result<Value> {
    return Ok((if (value.clone().is_array()) {
        {
            let mut collected_values = Vec::new();
            for current in sequence(&value)? {
                let mut item = current;
                if !(truth(&json!(values::text(&item)))) {
                    continue;
                }
                collected_values.push(json!(values::text(&item)));
            }
            Value::Array(collected_values)
        }
    } else {
        Value::Array(vec![])
    }));
}
